-- Scoped kitchen duties, confirmed monotone quantities and order human control.

CREATE TABLE _dg_native_order_kitchen_results(action_id text PRIMARY KEY REFERENCES _dg_native_dining_actions(id),ticket_id text NOT NULL REFERENCES restaurant_kitchen_tickets(id),mode text NOT NULL CHECK(mode IN('cook','serve')),created_at text NOT NULL);
CREATE TABLE _dg_native_order_kitchen_revisions(ticket_id text NOT NULL REFERENCES restaurant_kitchen_tickets(id),version bigint NOT NULL,action_id text NOT NULL REFERENCES _dg_native_dining_actions(id),row_hash text NOT NULL,created_at text NOT NULL,PRIMARY KEY(ticket_id,version));
CREATE TRIGGER native_order_kitchen_result_immutable BEFORE UPDATE OR DELETE ON _dg_native_order_kitchen_results FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
CREATE TRIGGER native_order_kitchen_revision_immutable BEFORE UPDATE OR DELETE ON _dg_native_order_kitchen_revisions FOR EACH ROW EXECUTE FUNCTION dg_native_append_only();
-- Preserve a baseline revision when upgrading an existing native instance.
INSERT INTO _dg_native_order_kitchen_revisions SELECT ticket.id,ticket.version,latest.id,dg_native_office_hash(to_jsonb(ticket)),latest.created_at FROM restaurant_kitchen_tickets ticket JOIN _dg_native_order_kitchen_origins fixed ON fixed.ticket_id=ticket.id CROSS JOIN LATERAL(SELECT action.id,action.created_at FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions action ON action.id=effect.action_id WHERE effect.table_name='restaurant_kitchen_tickets' AND effect.resource_id=ticket.id ORDER BY action.created_at DESC,action.id DESC LIMIT 1) latest;

CREATE FUNCTION dg_native_order_kitchen_authority(actor_value text,restaurant_value text,epoch_value bigint,grant_value bigint,mode_value text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
 SELECT mode_value IN('read','cook','serve') AND EXISTS(SELECT 1 FROM memberships member JOIN _dg_native_restaurant_member_epochs epoch ON epoch.user_id=member.user_id JOIN restaurants restaurant ON restaurant.tenant_id=member.tenant_id JOIN _dg_native_restaurant_origins fixed ON fixed.restaurant_id=restaurant.id LEFT JOIN restaurant_staff staff ON staff.restaurant_id=restaurant.id AND staff.user_id=member.user_id WHERE member.user_id=actor_value AND restaurant.id=restaurant_value AND member.workspace_ids::jsonb ? restaurant.workspace_id AND epoch.epoch=epoch_value AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND restaurant.environment='mock' AND restaurant.app_env=(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) AND(member.role='admin' AND grant_value=0 OR staff.enabled=1 AND staff.version=grant_value AND(staff.expires_at IS NULL OR staff.expires_at>dg_native_dining_now()) AND(staff.role='manager' OR mode_value='read' AND staff.role IN('host','kitchen') OR mode_value='cook' AND staff.role='kitchen' OR mode_value='serve' AND staff.role='host')))
$dg$;

CREATE FUNCTION dg_native_order_kitchen_context(kind_value text,target text,write_value boolean DEFAULT false,mode_value text DEFAULT 'read') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE member memberships%ROWTYPE;r restaurants%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;o restaurant_orders%ROWTYPE;restaurant_value text;epoch_value bigint;grant_value bigint;
BEGIN
 member:=dg_native_restaurant_actor();IF kind_value='restaurant' THEN restaurant_value:=target;ELSIF kind_value='ticket' THEN SELECT current_ticket.* INTO ticket FROM restaurant_kitchen_tickets current_ticket JOIN _dg_native_order_kitchen_origins fixed ON fixed.ticket_id=current_ticket.id WHERE current_ticket.id=target AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1);restaurant_value:=ticket.restaurant_id;ELSE PERFORM dg_native_order_error('VALIDATION_FAILED');END IF;
 SELECT * INTO r FROM restaurants WHERE id=restaurant_value;SELECT epoch INTO epoch_value FROM _dg_native_restaurant_member_epochs WHERE user_id=member.user_id;SELECT CASE WHEN member.role='admin' THEN 0 ELSE version END INTO grant_value FROM restaurant_staff WHERE restaurant_id=r.id AND user_id=member.user_id;IF member.role='admin' THEN grant_value:=0;END IF;
 IF NOT coalesce(dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,grant_value,mode_value),false) THEN PERFORM dg_native_order_error('NOT_FOUND');END IF;
 PERFORM dg_native_reception_workspace(r.tenant_id,r.workspace_id,write_value);IF write_value THEN PERFORM id FROM restaurants WHERE id=r.id FOR UPDATE;ELSE PERFORM id FROM restaurants WHERE id=r.id FOR SHARE;END IF;
 IF NOT dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,grant_value,mode_value) THEN PERFORM dg_native_order_error('AUTHORIZATION_CHANGED');END IF;
 IF ticket.id IS NOT NULL THEN IF write_value THEN SELECT * INTO o FROM restaurant_orders WHERE id=ticket.order_id FOR UPDATE;SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=target FOR UPDATE;ELSE SELECT * INTO o FROM restaurant_orders WHERE id=ticket.order_id;END IF;END IF;
 RETURN jsonb_build_object('actorType','staff','actorId',member.user_id,'actorEpoch',epoch_value,'grantVersion',grant_value,'sessionId',NULL,'accessId',NULL,'focusVersion',NULL,'selectionVersion',NULL,'restaurantId',r.id,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'partyId',o.party_id,'orderId',o.id,'ticketId',ticket.id,'canCook',dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,grant_value,'cook'),'canServe',dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,grant_value,'serve'));
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_directory() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE member memberships%ROWTYPE;epoch_value bigint;result jsonb;
BEGIN
 member:=dg_native_restaurant_actor();SELECT epoch INTO epoch_value FROM _dg_native_restaurant_member_epochs WHERE user_id=member.user_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'name',r.name,'workspaceId',r.workspace_id,'canCook',dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,CASE WHEN member.role='admin' THEN 0 ELSE staff.version END,'cook'),'canServe',dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,CASE WHEN member.role='admin' THEN 0 ELSE staff.version END,'serve')) ORDER BY r.name,r.id),'[]') INTO result FROM restaurants r LEFT JOIN restaurant_staff staff ON staff.restaurant_id=r.id AND staff.user_id=member.user_id WHERE dg_native_order_kitchen_authority(member.user_id,r.id,epoch_value,CASE WHEN member.role='admin' THEN 0 ELSE staff.version END,'read');RETURN result;
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE ticket restaurant_kitchen_tickets%ROWTYPE;line restaurant_order_lines%ROWTYPE;o restaurant_orders%ROWTYPE;active bigint;state_value text;
BEGIN
 SELECT t.* INTO ticket FROM restaurant_kitchen_tickets t JOIN _dg_native_order_kitchen_origins fixed ON fixed.ticket_id=t.id WHERE t.id=target AND t.restaurant_id=meta->>'restaurantId' AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1);IF ticket.id IS NULL THEN PERFORM dg_native_order_error('NOT_FOUND');END IF;SELECT * INTO line FROM restaurant_order_lines WHERE id=ticket.line_id;SELECT * INTO o FROM restaurant_orders WHERE id=ticket.order_id;active:=line.quantity-line.cancelled_quantity;
 state_value:=CASE WHEN active=0 THEN 'cancelled' WHEN ticket.served_quantity>=active THEN 'served' WHEN ticket.ready_quantity>=active THEN 'ready' WHEN ticket.started_quantity>0 THEN 'preparing' ELSE 'accepted' END;
 RETURN jsonb_build_object('id',ticket.id,'restaurantId',ticket.restaurant_id,'orderNumber',o.number,'tableName',ticket.table_name,'tableCode',ticket.table_code,'itemName',line.item_name,'skuName',line.sku_name,'quantity',line.quantity,'activeQuantity',active,'cancelledQuantity',line.cancelled_quantity,'startedQuantity',ticket.started_quantity,'readyQuantity',ticket.ready_quantity,'servedQuantity',ticket.served_quantity,'pendingCancelQuantity',ticket.pending_cancel_quantity,'preparationNote',line.preparation_note,'dietaryTags',line.dietary_tags::jsonb,'version',ticket.version,'state',state_value,'canCook',(meta->>'canCook')::boolean,'canServe',(meta->>'canServe')::boolean,'acceptedAt',ticket.accepted_at,'updatedAt',ticket.updated_at);
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_read(target text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;result jsonb;
BEGIN meta:=dg_native_order_kitchen_context('restaurant',target);SELECT coalesce(jsonb_agg(dg_native_order_kitchen_project(ticket.id,meta) ORDER BY ticket.accepted_at,ticket.id),'[]') INTO result FROM restaurant_kitchen_tickets ticket JOIN _dg_native_order_kitchen_origins fixed ON fixed.ticket_id=ticket.id WHERE ticket.restaurant_id=target;RETURN result;END;$dg$;

CREATE FUNCTION dg_native_order_status(target text,ignore_control boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE o restaurant_orders%ROWTYPE;c restaurant_order_changes%ROWTYPE;active bigint;started bigint;ready bigint;served bigint;
BEGIN
 SELECT * INTO o FROM restaurant_orders WHERE id=target;IF o.status IN('closed','cancelled') THEN RETURN o.status;END IF;IF o.control_mode='human' AND NOT ignore_control THEN RETURN 'needs_attention';END IF;SELECT * INTO c FROM restaurant_order_changes WHERE id=o.pending_change_id;
 IF c.status IN('draft','awaiting_confirmation','confirmed','queued','submitting','submitted') THEN RETURN c.status;ELSIF c.status='unknown' THEN RETURN 'needs_attention';END IF;
 SELECT coalesce(sum(line.quantity-line.cancelled_quantity),0),coalesce(sum(ticket.started_quantity),0),coalesce(sum(ticket.ready_quantity),0),coalesce(sum(ticket.served_quantity),0) INTO active,started,ready,served FROM restaurant_order_lines line JOIN restaurant_kitchen_tickets ticket ON ticket.line_id=line.id WHERE line.order_id=o.id;
 IF active>0 THEN RETURN(CASE WHEN served>=active THEN 'served' WHEN ready>=active THEN 'ready' WHEN started>0 THEN 'preparing' ELSE 'accepted' END);END IF;
 IF EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id) THEN RETURN 'cancelled';END IF;SELECT * INTO c FROM restaurant_order_changes WHERE order_id=o.id ORDER BY sequence DESC LIMIT 1;RETURN(CASE WHEN c.status IN('withdrawn','stale') THEN 'cancelled' WHEN c.status IN('rejected','unknown') THEN 'needs_attention' ELSE 'draft' END);
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_apply(target text,input jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;ticket restaurant_kitchen_tickets%ROWTYPE;line restaurant_order_lines%ROWTYPE;o restaurant_orders%ROWTYPE;action_value text;created text;kind_value text:=input->>'action';mode_value text;quantity_value bigint;available bigint;
BEGIN
 PERFORM dg_native_restaurant_fields(input,ARRAY['version','action','quantity','confirmed']);IF kind_value NOT IN('start','ready','serve') OR kind_value IS NULL OR input->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_order_error('VALIDATION_FAILED');END IF;quantity_value:=dg_native_restaurant_integer(input->'quantity',1,99);mode_value:=CASE WHEN kind_value='serve' THEN 'serve' ELSE 'cook' END;meta:=dg_native_order_kitchen_context('ticket',target,true,mode_value);
 SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=target;SELECT * INTO line FROM restaurant_order_lines WHERE id=ticket.line_id;SELECT * INTO o FROM restaurant_orders WHERE id=ticket.order_id;
 IF dg_native_restaurant_integer(input->'version',1,9007199254740991)<>ticket.version THEN PERFORM dg_native_order_error('VERSION_CONFLICT');END IF;
 IF EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND dispatch.error_code='POS_RECONCILIATION_REQUIRED') THEN PERFORM dg_native_order_error('POS_RECONCILIATION_REQUIRED');END IF;
 available:=CASE kind_value WHEN 'start' THEN line.quantity-line.cancelled_quantity-ticket.started_quantity-ticket.pending_cancel_quantity WHEN 'ready' THEN ticket.started_quantity-ticket.ready_quantity ELSE ticket.ready_quantity-ticket.served_quantity END;
 IF o.status IN('closed','cancelled') OR quantity_value>available THEN PERFORM dg_native_order_error('KITCHEN_QUANTITY_CHANGED');END IF;
 action_value:=dg_native_dining_action(meta,'kitchen_'||kind_value,'party',meta->>'partyId',input);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket.id);
 UPDATE restaurant_kitchen_tickets SET started_quantity=started_quantity+CASE WHEN kind_value='start' THEN quantity_value ELSE 0 END,ready_quantity=ready_quantity+CASE WHEN kind_value='ready' THEN quantity_value ELSE 0 END,served_quantity=served_quantity+CASE WHEN kind_value='serve' THEN quantity_value ELSE 0 END,version=version+1,updated_at=created WHERE id=ticket.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET status=dg_native_order_status(o.id),version=version+1,updated_at=created WHERE id=o.id;PERFORM dg_native_order_event(action_value,o.id,NULL,'kitchen_'||kind_value,'店员已按当前制作单明确核对本次实际处理数量。');INSERT INTO _dg_native_order_kitchen_results VALUES(action_value,ticket.id,mode_value,created);RETURN action_value;
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_result(target text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE receipt _dg_native_order_kitchen_results%ROWTYPE;action _dg_native_dining_actions%ROWTYPE;meta jsonb;
BEGIN
 SELECT * INTO receipt FROM _dg_native_order_kitchen_results WHERE action_id=target;SELECT * INTO action FROM _dg_native_dining_actions WHERE id=target;IF receipt.action_id IS NULL OR action.id IS NULL THEN PERFORM dg_native_order_error('NOT_FOUND');END IF;meta:=dg_native_order_kitchen_context('ticket',receipt.ticket_id,false,receipt.mode);
 IF action.actor_type<>'staff' OR action.actor_id IS DISTINCT FROM meta->>'actorId' OR action.actor_epoch IS DISTINCT FROM(meta->>'actorEpoch')::bigint OR action.grant_version IS DISTINCT FROM(meta->>'grantVersion')::bigint THEN PERFORM dg_native_order_error('AUTHORIZATION_CHANGED');END IF;RETURN dg_native_order_kitchen_project(receipt.ticket_id,meta);
END;$dg$;

CREATE FUNCTION dg_native_order_control(target text,input jsonb,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;body jsonb:=input-ARRAY['focusVersion','selectionVersion'];o restaurant_orders%ROWTYPE;c restaurant_order_changes%ROWTYPE;action_value text;withdraw_action text;created text;kind_value text:=body->>'action';
BEGIN
 meta:=dg_native_order_context('order',target,session_value,token_value,csrf_value,focus_value,true);PERFORM dg_native_order_input(meta,input);PERFORM dg_native_restaurant_fields(body,ARRAY['version','action','reason','confirmed']);PERFORM dg_native_restaurant_text(body->'reason',3,200);IF kind_value NOT IN('handoff','resume') OR kind_value IS NULL OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_order_error('VALIDATION_FAILED');END IF;SELECT * INTO o FROM restaurant_orders WHERE id=target FOR UPDATE;
 IF dg_native_restaurant_integer(body->'version',1,9007199254740991)<>o.version THEN PERFORM dg_native_order_error('VERSION_CONFLICT');END IF;IF o.status IN('closed','cancelled') OR o.settlement_status<>'unsettled' OR(kind_value='handoff')=(o.control_mode='human') THEN PERFORM dg_native_order_error('ORDER_NOT_WRITABLE');END IF;
 IF kind_value='resume' THEN
  IF meta->>'actorType'<>'staff' THEN PERFORM dg_native_order_error('FORBIDDEN');END IF;
  IF EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND dispatch.error_code='POS_RECONCILIATION_REQUIRED') THEN PERFORM dg_native_order_error('POS_RECONCILIATION_REQUIRED');END IF;
  IF EXISTS(SELECT 1 FROM restaurant_order_dispatches dispatch JOIN restaurant_order_changes change ON change.id=dispatch.change_id WHERE change.order_id=o.id AND dispatch.status IN('submitting','submitted','unknown')) THEN PERFORM dg_native_order_error('ORDER_RESULT_PENDING');END IF;
 ELSIF o.pending_change_id IS NOT NULL THEN
  SELECT * INTO c FROM restaurant_order_changes WHERE id=o.pending_change_id;
  IF c.status IN('draft','awaiting_confirmation','confirmed','queued') THEN withdraw_action:=dg_native_dining_action(meta,'order_withdraw','party',meta->>'partyId',jsonb_build_object('source','explicit_human_handoff','originalOrderVersion',o.version));PERFORM dg_native_order_withdraw_internal(c.id,withdraw_action,false);SELECT * INTO o FROM restaurant_orders WHERE id=target;END IF;
 END IF;
 IF(SELECT count(*) FROM _dg_native_dining_actions WHERE kind='order_control' AND resource_id=meta->>'partyId' AND created_at>dg_native_people_iso(clock_timestamp()-interval '5 minutes'))>=40 THEN PERFORM dg_native_order_error('RATE_LIMITED');END IF;
 action_value:=dg_native_dining_action(meta,'order_control','party',meta->>'partyId',body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET control_mode=CASE WHEN kind_value='handoff' THEN 'human' ELSE 'automatic' END,attention_reason=CASE WHEN kind_value='handoff' THEN '已请求店员核对；已发送请求仍须按原请求确认结果。' END,status=CASE WHEN status IN('closed','cancelled') THEN status WHEN kind_value='handoff' THEN 'needs_attention' ELSE dg_native_order_status(o.id,true) END,version=version+1,updated_at=created WHERE id=o.id;PERFORM dg_native_order_event(action_value,o.id,NULL,'order_control',CASE WHEN kind_value='handoff' THEN '已转人工；尚未发送的变更已撤回，已发送请求保留并继续核实。' ELSE '店员已明确核对并恢复后续自动处理，原可信事实不变。' END);INSERT INTO _dg_native_order_results VALUES(action_value,meta->>'restaurantId',o.id,NULL,NULL,(meta->>'partyAccessVersion')::bigint,created);RETURN action_value;
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE order_value text;record_value text;restaurant_value text;party_value text;action _dg_native_dining_actions%ROWTYPE;column_value text;quantity_value bigint;mode_value text;
BEGIN
 record_value:=j->>'id';IF table_value='restaurant_orders' THEN order_value:=record_value;ELSIF table_value IN('restaurant_kitchen_tickets','restaurant_order_events') THEN order_value:=j->>'order_id';ELSE RETURN false;END IF;SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 SELECT actual.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id AND actual.restaurant_id=restaurant_value AND actual.resource_id=party_value AND actual.kind IN('kitchen_start','kitchen_ready','kitchen_serve','order_control') ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;IF action.id IS NULL THEN RETURN false;END IF;
 IF operation_value='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen and human-control business history cannot be deleted';END IF;
 IF table_value='restaurant_kitchen_tickets' THEN
  column_value:=CASE action.kind WHEN 'kitchen_start' THEN 'started_quantity' WHEN 'kitchen_ready' THEN 'ready_quantity' WHEN 'kitchen_serve' THEN 'served_quantity' END;mode_value:=CASE WHEN action.kind='kitchen_serve' THEN 'serve' ELSE 'cook' END;
  IF column_value IS NULL OR operation_value<>'UPDATE' OR j-ARRAY[column_value,'version','updated_at'] IS DISTINCT FROM previous-ARRAY[column_value,'version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR NOT dg_native_order_kitchen_authority(action.actor_id,restaurant_value,action.actor_epoch,action.grant_version,mode_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen transitions retain exact original scope, authority and other counters';END IF;quantity_value:=(j->>column_value)::bigint-(previous->>column_value)::bigint;
  IF quantity_value NOT BETWEEN 1 AND 99 OR action.body_hash<>dg_native_office_hash(jsonb_build_object('version',(previous->>'version')::bigint,'action',substring(action.kind FROM 9),'quantity',quantity_value,'confirmed',true)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A monotone kitchen delta is the exact explicitly confirmed operation';END IF;
 ELSIF table_value='restaurant_orders' THEN
  IF operation_value<>'UPDATE' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'status' NOT IN('draft','awaiting_confirmation','confirmed','queued','submitting','submitted','needs_attention','accepted','preparing','ready','served','cancelled','closed') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen and human operations advance one current order version';END IF;
  IF action.kind='order_control' THEN
   IF j-ARRAY['status','version','control_mode','attention_reason','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','control_mode','attention_reason','updated_at'] OR j->>'control_mode' NOT IN('automatic','human') OR j->>'control_mode'=previous->>'control_mode' OR j->>'attention_reason' IS DISTINCT FROM(CASE WHEN j->>'control_mode'='human' THEN '已请求店员核对；已发送请求仍须按原请求确认结果。' END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Human control cannot change prices, content, payment, request identity or remote facts';END IF;
  ELSIF j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen progress cannot rewrite order contents, control or settlement';END IF;
 ELSE
  IF operation_value<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen events retain their actual actor and operation';END IF;
 END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_order_kitchen_history() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE action_value text;created text;
BEGIN
 SELECT action.id,action.created_at INTO action_value,created FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions action ON action.id=effect.action_id WHERE effect.table_name='restaurant_kitchen_tickets' AND effect.resource_id=NEW.id AND effect.transaction_id=pg_current_xact_id()::text AND action.transaction_id=effect.transaction_id ORDER BY action.created_at DESC,action.id DESC LIMIT 1;IF action_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every kitchen revision has its actual durable operation';END IF;INSERT INTO _dg_native_order_kitchen_revisions VALUES(NEW.id,NEW.version,action_value,dg_native_office_hash(to_jsonb(NEW)),created);RETURN NULL;
END;$dg$;
CREATE TRIGGER native_order_kitchen_history AFTER INSERT OR UPDATE ON restaurant_kitchen_tickets FOR EACH ROW EXECUTE FUNCTION dg_native_order_kitchen_history();

CREATE FUNCTION dg_native_order_kitchen_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);ticket restaurant_kitchen_tickets%ROWTYPE;o restaurant_orders%ROWTYPE;receipt _dg_native_order_kitchen_results%ROWTYPE;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='restaurant_orders' THEN SELECT * INTO o FROM restaurant_orders WHERE id=j->>'id';IF o.status IS DISTINCT FROM dg_native_order_status(o.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order status must match the actual pending change, human control and accepted kitchen counts';END IF;RETURN NULL;
 ELSIF TG_TABLE_NAME='_dg_native_order_kitchen_results' THEN
  SELECT * INTO receipt FROM _dg_native_order_kitchen_results WHERE action_id=j->>'action_id';SELECT * INTO action FROM _dg_native_dining_actions WHERE id=receipt.action_id;SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=receipt.ticket_id;
  IF action.kind NOT IN('kitchen_start','kitchen_ready','kitchen_serve') OR action.created_at<>receipt.created_at OR receipt.mode IS DISTINCT FROM(CASE WHEN action.kind='kitchen_serve' THEN 'serve' ELSE 'cook' END) OR NOT dg_native_order_kitchen_authority(action.actor_id,ticket.restaurant_id,action.actor_epoch,action.grant_version,receipt.mode) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen operation receipts commit with their original live duty';END IF;RETURN NULL;
 END IF;
 SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=j->>'id';IF NOT EXISTS(SELECT 1 FROM _dg_native_order_kitchen_revisions revision JOIN _dg_native_dining_actions action ON action.id=revision.action_id WHERE revision.ticket_id=ticket.id AND revision.version=ticket.version AND revision.row_hash=dg_native_office_hash(to_jsonb(ticket)) AND revision.created_at=ticket.updated_at AND action.kind IN('order_receipt','order_submit','order_withdraw','order_expire','kitchen_start','kitchen_ready','kitchen_serve')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen current row equals its latest immutable exact revision';END IF;RETURN NULL;
END;$dg$;
CREATE CONSTRAINT TRIGGER native_order_kitchen_final AFTER INSERT OR UPDATE ON restaurant_kitchen_tickets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_order_kitchen_final();
CREATE CONSTRAINT TRIGGER native_order_kitchen_final AFTER INSERT ON _dg_native_order_kitchen_results DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_order_kitchen_final();
CREATE CONSTRAINT TRIGGER native_order_kitchen_order_final AFTER INSERT OR UPDATE ON restaurant_orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_order_kitchen_final();

CREATE OR REPLACE FUNCTION dg_native_order_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);previous jsonb:=to_jsonb(OLD);record_value text;restaurant_value text;party_value text;order_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF dg_native_order_kitchen_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 IF dg_native_order_transport_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 record_value:=CASE TG_TABLE_NAME WHEN 'restaurant_pos_configs' THEN j->>'restaurant_id' WHEN 'restaurant_order_dispatches' THEN j->>'change_id' ELSE j->>'id' END;
 IF TG_OP='DELETE' OR NOT dg_native_dining_changed(TG_TABLE_NAME,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order records require their actual scoped operation';END IF;
 IF TG_TABLE_NAME='restaurant_pos_configs' THEN restaurant_value:=j->>'restaurant_id';
 ELSIF TG_TABLE_NAME='restaurant_orders' THEN restaurant_value:=j->>'restaurant_id';party_value:=j->>'party_id';
 ELSE
  order_value:=CASE WHEN TG_TABLE_NAME='restaurant_order_changes' OR TG_TABLE_NAME='restaurant_order_events' OR TG_TABLE_NAME='restaurant_kitchen_tickets' THEN j->>'order_id' ELSE(SELECT c.order_id FROM restaurant_order_changes c WHERE c.id=j->>'change_id') END;
  SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 END IF;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=coalesce(party_value,restaurant_value) AND a.kind IN('order_config','order_draft','order_update','order_review','order_confirm','order_submit','order_withdraw','order_expire','order_quote_expire') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order effects cannot borrow unrelated business actions';END IF;
 IF TG_TABLE_NAME='restaurant_orders' THEN
  IF j->>'control_mode' NOT IN('automatic','human') OR j->>'settlement_status'<>'unsettled' OR(TG_OP='INSERT' AND(j->>'attention_reason' IS NOT NULL OR j->>'control_mode'<>'automatic')) OR(TG_OP='INSERT' AND(j->>'remote_order_id' IS NOT NULL OR(j->>'content_version')::bigint<>1)) OR j->>'status' NOT IN('draft','awaiting_confirmation','confirmed','queued','cancelled','accepted','preparing','ready','served','needs_attention') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This order stage cannot fabricate acceptance, payment or remote facts';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'pending_change_id' IS NOT NULL OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order creation is an unsubmitted original draft';END IF;
  ELSIF j-ARRAY['version','status','pending_change_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','pending_change_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR previous->>'status' IN('closed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order identity, accepted content and terminal states cannot be rewritten';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_changes' THEN
  IF j->>'source'<>'manual' OR j->>'source_request_id' IS NOT NULL OR j->>'kind' NOT IN('initial','amend','cancel') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Drafts cannot claim a fabricated conversation or source';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'created_at'<>action.created_at OR j->>'confirmed_at' IS NOT NULL OR j->>'current_quote_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order changes start as the next editable draft';END IF;
  ELSE
   IF j-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Change scope, sequence, source and version are immutable';END IF;
   IF NOT(action.kind='order_update' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='draft' OR action.kind='order_review' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='awaiting_confirmation' OR action.kind='order_confirm' AND previous->>'status'='awaiting_confirmation' AND j->>'status'='confirmed' OR action.kind='order_submit' AND previous->>'status'='confirmed' AND j->>'status'='queued' OR action.kind='order_withdraw' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed','queued','rejected','stale') AND j->>'status'='withdrawn' OR action.kind='order_expire' AND previous->>'status'='queued' AND j->>'status'='stale') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported order change transition';END IF;
   IF action.kind<>'order_update' AND j-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Review, confirmation and dispatch cannot rewrite draft input or attribution';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_quotes' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_review' OR j->>'status'<>'current' OR j->>'created_at'<>action.created_at OR(j->>'expires_at')::timestamptz<>(j->>'created_at')::timestamptz+interval '120 seconds' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quotes keep a fixed original two-minute deadline';END IF;
  ELSIF j-'status' IS DISTINCT FROM previous-'status' OR previous->>'status'<>'current' OR j->>'status' NOT IN('superseded','withdrawn','expired') OR j->>'status'='expired' AND j->>'expires_at'>dg_native_dining_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote content, attribution and original deadline cannot be replaced';END IF;
 ELSIF TG_TABLE_NAME='restaurant_pos_configs' THEN
  IF action.kind<>'order_config' OR j->>'provider_id' NOT IN('mock-pos','external-pos') OR(j->>'enabled')::bigint NOT IN(0,1) OR j->>'provider_id'='external-pos' AND j->>'enabled'<>'0' OR j->>'scenario' NOT IN('normal','rejected','response_lost','unresolved') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native POS configuration cannot silently simulate a live provider';END IF;
  IF TG_OP='INSERT' THEN IF(j->>'version')::bigint<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config starts at version one';END IF;
  ELSIF j-ARRAY['provider_id','enabled','scenario','version','updated_at'] IS DISTINCT FROM previous-ARRAY['provider_id','enabled','scenario','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config versions and original creation are guarded';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'queued' OR j->>'attempts'<>'0' OR j->>'version'<>'1' OR j->>'simulated'<>'1' OR j->>'provider_id'<>'mock-pos' OR j->>'lease_token' IS NOT NULL OR j->>'lease_until' IS NOT NULL OR j->>'remote_request_id' IS NOT NULL OR j->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A persistent dispatch is queued and has not claimed external success';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'queued' OR previous->>'attempts'<>'0' OR j->>'status'<>'cancelled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['status','version','error_code','error_message','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','error_code','error_message','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only definitely unsent dispatches can be withdrawn in this stage';END IF;
 ELSIF TG_TABLE_NAME='restaurant_inventory_reservations' THEN
  IF(j->>'quantity')::bigint<=0 OR j->>'tracked' NOT IN('0','1') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Inventory reservation quantities are positive and explicitly tracked';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'reserved' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reservations originate in the atomic submit';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'reserved' OR j->>'status'<>'released' OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only original reservations can be released once';END IF;
 ELSIF TG_TABLE_NAME='restaurant_stock_movements' THEN
  IF TG_OP<>'INSERT' OR j->>'kind' NOT IN('reserve','release') OR(j->>'before_quantity')::bigint<0 OR(j->>'after_quantity')::bigint<0 OR NOT(action.kind='order_submit' AND j->>'kind'='reserve' AND(j->>'before_quantity')::bigint>(j->>'after_quantity')::bigint OR action.kind IN('order_withdraw','order_expire') AND j->>'kind'='release' AND(j->>'before_quantity')::bigint<(j->>'after_quantity')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock movements are append-only actual reservation or release deltas';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_events' THEN
  IF TG_OP<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order events retain their actual operation and actor';END IF;
 ELSE
  IF TG_TABLE_NAME<>'restaurant_kitchen_tickets' OR TG_OP<>'UPDATE' OR action.kind NOT IN('order_submit','order_withdraw','order_expire') OR j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This stage cannot fabricate kitchen progress';END IF;
 END IF;RETURN NEW;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_dining_business_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);party_value text;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;origin _dg_native_dining_party_origins%ROWTYPE;b dining_reservations%ROWTYPE;o dining_occupancies%ROWTYPE;t restaurant_tables%ROWTYPE;plan dining_hold_plans%ROWTYPE;a _dg_native_dining_actions%ROWTYPE;s reception_sessions%ROWTYPE;booking_clock _dg_native_dining_booking_clocks%ROWTYPE;latest record;
BEGIN
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'id';SELECT * INTO r FROM restaurants WHERE id=a.restaurant_id;
  IF a.actor_type='staff' AND NOT(CASE WHEN a.kind IN('kitchen_start','kitchen_ready','kitchen_serve') THEN dg_native_order_kitchen_authority(a.actor_id,a.restaurant_id,a.actor_epoch,a.grant_version,CASE WHEN a.kind='kitchen_serve' THEN 'serve' ELSE 'cook' END) ELSE dg_native_dining_clock_authority(a.actor_id,a.restaurant_id,a.actor_epoch,a.grant_version) END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining staff operation must commit with its original current authority';END IF;
  IF a.resource_type='restaurant' THEN
   IF a.kind<>'order_config' OR a.actor_type<>'staff' OR a.resource_id IS DISTINCT FROM r.id OR r.environment<>'mock' OR r.app_env IS DISTINCT FROM(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_pos_revisions fixed WHERE fixed.action_id=a.id AND fixed.restaurant_id=r.id AND fixed.created_at=a.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Store configuration action requires its exact immutable POS revision';END IF;RETURN NULL;
  END IF;
  IF a.actor_type='guest' THEN SELECT * INTO s FROM reception_sessions WHERE id=a.session_id;IF s.status<>'active' OR s.expires_at<=dg_native_dining_now() OR NOT dg_native_reception_source_valid(s.id) OR s.focus_version<>a.focus_version OR NOT EXISTS(SELECT 1 FROM _dg_native_reception_access WHERE id=a.access_id AND session_id=s.id AND access_version=s.access_version) OR coalesce((SELECT max(version) FROM _dg_native_dining_selection_revisions WHERE session_id=s.id),0)<>a.selection_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining guest operation keeps its actual session, access, person and selection';END IF;END IF;
  IF a.resource_type='plan' THEN SELECT party_id INTO party_value FROM dining_hold_plans WHERE id=a.resource_id;ELSE party_value:=a.resource_id;END IF;
 ELSIF TG_TABLE_NAME='_dg_native_dining_selection_revisions' THEN
  SELECT * INTO s FROM reception_sessions WHERE id=j->>'session_id';SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'action_id';SELECT version,party_id INTO latest FROM _dg_native_dining_selection_revisions WHERE session_id=s.id ORDER BY version DESC LIMIT 1;
  IF s.service_scene<>'restaurant' OR latest.party_id IS DISTINCT FROM s.dining_party_id OR (j->>'version')::bigint<>coalesce((SELECT max(version) FROM _dg_native_dining_selection_revisions WHERE session_id=s.id AND version<(j->>'version')::bigint),0)+1 OR a.transaction_id<>pg_current_xact_id()::text OR a.kind NOT IN('create','reserve','select','claim') OR NOT dg_native_dining_changed('reception_sessions',s.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining selection revisions preserve their original monotonic target';END IF;RETURN NULL;
 ELSIF TG_TABLE_NAME='dining_parties' THEN party_value:=j->>'id';
 ELSIF TG_TABLE_NAME='_dg_native_dining_party_origins' THEN party_value:=j->>'party_id';
 ELSIF TG_TABLE_NAME IN('dining_reservations','dining_occupancies','dining_hold_plans') THEN party_value:=j->>'party_id';
 ELSIF TG_TABLE_NAME='_dg_native_dining_plan_origins' THEN SELECT * INTO plan FROM dining_hold_plans WHERE id=j->>'plan_id';party_value:=plan.party_id;
 ELSIF TG_TABLE_NAME='_dg_native_dining_occupancy_origins' THEN SELECT * INTO o FROM dining_occupancies WHERE id=j->>'occupancy_id';party_value:=o.party_id;
 ELSIF TG_TABLE_NAME='_dg_native_dining_booking_clocks' THEN
  SELECT * INTO b FROM dining_reservations WHERE id=j->>'reservation_id';SELECT * INTO a FROM _dg_native_dining_actions WHERE id=j->>'action_id';party_value:=b.party_id;
  IF a.transaction_id<>pg_current_xact_id()::text OR a.kind NOT IN('reserve','reschedule') OR a.resource_id<>party_value OR(j->>'revision')::bigint<>b.version OR j->>'starts_at' IS DISTINCT FROM b.starts_at OR j->>'ends_at' IS DISTINCT FROM b.ends_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Booking clock revisions require the actual confirmed time operation';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported dining invariant source';END IF;
 SELECT * INTO p FROM dining_parties WHERE id=party_value;SELECT * INTO origin FROM _dg_native_dining_party_origins WHERE party_id=p.id;SELECT * INTO r FROM restaurants WHERE id=p.restaurant_id;
 IF p.id IS NULL OR origin.party_id IS NULL OR origin.restaurant_id<>p.restaurant_id OR origin.runtime_id IS DISTINCT FROM(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.tenant_id<>r.tenant_id OR origin.workspace_id<>r.workspace_id OR origin.created_at<>p.created_at OR p.owner_session_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM _dg_native_dining_session_origins WHERE session_id=p.owner_session_id AND restaurant_id=r.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining facts retain native runtime, store and consent ownership';END IF;
 SELECT * INTO b FROM dining_reservations WHERE party_id=p.id;SELECT * INTO o FROM dining_occupancies WHERE party_id=p.id AND state IN('held','seated');
 IF p.status='reserved' AND(b.id IS NULL OR b.status<>'confirmed') OR p.status='held' AND(o.id IS NULL OR o.state<>'held') OR p.status='seated' AND(o.id IS NULL OR o.state<>'seated') OR p.status NOT IN('held','seated') AND o.id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining party state and actual occupancy must agree';END IF;
 IF b.id IS NOT NULL THEN
  booking_clock:=dg_native_dining_booking_clock(b.id);IF booking_clock.reservation_id IS NULL OR booking_clock.starts_at<>b.starts_at OR booking_clock.ends_at<>b.ends_at OR booking_clock.checkin_opens_at<>dg_native_people_iso(b.starts_at::timestamptz-interval '30 minutes') OR booking_clock.late_deadline<b.starts_at OR booking_clock.late_deadline>dg_native_people_iso(b.starts_at::timestamptz+interval '60 minutes') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reservation clocks retain their original confirmed time revision';END IF;
  SELECT * INTO t FROM restaurant_tables WHERE id=b.table_id;IF b.restaurant_id<>r.id OR t.restaurant_id<>r.id OR b.status IN('confirmed','checked_in') AND NOT dg_native_dining_fits(t,p.size) OR EXISTS(SELECT 1 FROM dining_reservations other WHERE other.restaurant_id=r.id AND other.id<>b.id AND other.table_id=b.table_id AND other.status IN('confirmed','checked_in') AND b.status IN('confirmed','checked_in') AND other.starts_at<b.ends_at AND other.ends_at>b.starts_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining reservations cannot overlap or lose their scoped table capacity';END IF;
 END IF;
 IF o.id IS NOT NULL THEN
  SELECT * INTO t FROM restaurant_tables WHERE id=o.table_id;IF o.restaurant_id<>r.id OR t.restaurant_id<>r.id OR NOT dg_native_dining_fits(t,p.size) OR t.operation<>'open' OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_occupancy_origins WHERE occupancy_id=o.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Active dining occupancy requires its actual scoped, enabled table and immutable plan';END IF;
 END IF;
 IF TG_TABLE_NAME IN('dining_hold_plans','_dg_native_dining_plan_origins') THEN
  SELECT * INTO plan FROM dining_hold_plans WHERE id=CASE WHEN TG_TABLE_NAME='dining_hold_plans' THEN j->>'id' ELSE j->>'plan_id' END;SELECT action.* INTO a FROM _dg_native_dining_plan_origins binding JOIN _dg_native_dining_actions action ON action.id=binding.action_id WHERE binding.plan_id=plan.id;
  IF plan.id IS NULL OR a.id IS NULL OR a.kind<>'plan' OR a.resource_id<>plan.id OR a.restaurant_id<>plan.restaurant_id OR a.actor_id<>plan.actor_id OR a.focus_version IS DISTINCT FROM plan.focus_version OR NOT EXISTS(SELECT 1 FROM restaurant_tables WHERE id=plan.table_id AND restaurant_id=plan.restaurant_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dining plans keep the actual immutable action and table source';END IF;
 END IF;RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;order_value text;party_value text;restaurant_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 record_value:=CASE WHEN table_value IN('restaurant_order_dispatches','mock_pos_operations') THEN j->>'change_id' WHEN table_value='restaurant_pos_callbacks' THEN j->>'event_id' ELSE j->>'id' END;
 IF table_value='restaurant_orders' THEN order_value:=j->>'id';ELSIF table_value IN('restaurant_order_changes','restaurant_order_lines','restaurant_kitchen_tickets','restaurant_order_events') THEN order_value:=j->>'order_id';ELSE SELECT order_id INTO order_value FROM restaurant_order_changes WHERE id=j->>'change_id';END IF;
 SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=party_value AND a.kind IN('order_send','order_lookup','order_unknown','order_receipt','order_query','order_mock_fixture','order_mock_remote') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch and trusted business facts cannot be deleted';END IF;
 IF table_value='restaurant_orders' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'status' NOT IN('submitting','submitted','needs_attention','accepted','draft','cancelled','preparing','ready','served') OR j->>'settlement_status'<>'unsettled' OR(j->>'content_version')::bigint NOT BETWEEN(previous->>'content_version')::bigint AND(previous->>'content_version')::bigint+1 OR action.kind<>'order_receipt' AND j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] OR action.kind='order_receipt' AND j->>'remote_order_id' IS DISTINCT FROM previous->>'remote_order_id' AND previous->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport only changes order state or applies the original trusted content once';END IF;
 ELSIF table_value='restaurant_order_changes' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting' OR action.kind='order_lookup' AND previous->>'status'='submitting' AND j->>'status'='unknown' OR action.kind='order_unknown' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status'='unknown' OR action.kind='order_receipt' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status' IN('submitted','accepted','rejected','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport cannot rewrite draft identity, input or its original confirmation';END IF;
 ELSIF table_value='restaurant_order_dispatches' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'attempts')::bigint<>1 OR j->>'status' NOT IN('submitting','submitted','unknown','accepted','rejected') OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint OR(previous->>'attempts')::bigint=0 AND NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting') OR previous->>'status' IN('accepted','rejected') AND j->>'status' IS DISTINCT FROM previous->>'status' OR action.kind IN('order_query','order_mock_fixture') AND j-ARRAY['version','query_requested','updated_at'] IS DISTINCT FROM previous-ARRAY['version','query_requested','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts and the frozen original request cannot be reset or retargeted';END IF;
 ELSIF table_value='restaurant_order_quotes' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'current' OR j->>'status' NOT IN('accepted','rejected') OR j-'status' IS DISTINCT FROM previous-'status' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Final receipts consume the original quote without changing its deadline or contents';END IF;
 ELSIF table_value='restaurant_inventory_reservations' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'reserved' OR j->>'status' NOT IN('committed','released') OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only trusted final receipts commit or release existing reservations';END IF;
 ELSIF table_value='restaurant_stock_movements' THEN
  IF operation_value<>'INSERT' OR action.kind<>'order_receipt' OR j->>'kind' NOT IN('release','cancel_return') OR(j->>'after_quantity')::bigint<=(j->>'before_quantity')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock returns require the trusted original receipt';END IF;
 ELSIF table_value='restaurant_order_lines' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'cancelled_quantity')::bigint<>0 OR j->>'created_at'<>action.created_at) OR operation_value='UPDATE' AND(j-'cancelled_quantity' IS DISTINCT FROM previous-'cancelled_quantity' OR(j->>'cancelled_quantity')::bigint<=(previous->>'cancelled_quantity')::bigint OR(j->>'cancelled_quantity')::bigint>(j->>'quantity')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line snapshots are immutable except trusted cancelled quantities';END IF;
 ELSIF table_value='restaurant_kitchen_tickets' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'started_quantity')::bigint<>0 OR(j->>'ready_quantity')::bigint<>0 OR(j->>'served_quantity')::bigint<>0 OR(j->>'pending_cancel_quantity')::bigint<>0 OR(j->>'version')::bigint<>1 OR j->>'accepted_at'<>action.created_at) OR operation_value='UPDATE' AND(j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt creates original kitchen rows without inventing preparation progress';END IF;
 ELSIF table_value='restaurant_pos_callbacks' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND(j->>'created_at'<>action.created_at OR j->>'applied'<>'0' OR j->>'conflict'<>'0') OR operation_value='UPDATE' AND(j-ARRAY['applied','conflict'] IS DISTINCT FROM previous-ARRAY['applied','conflict'] OR previous->>'applied'<>'0' OR previous->>'conflict'<>'0' OR(j->>'applied')::bigint+(j->>'conflict')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt payload is immutable and has one terminal local application outcome';END IF;
 ELSIF table_value='mock_pos_operations' THEN
  IF operation_value<>'INSERT' OR action.kind NOT IN('order_mock_remote','order_mock_fixture') OR j->>'outcome' NOT IN('accepted','rejected') OR j->>'sequence'<>'2' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit local mock facts are append-only and cannot replace a real provider';END IF;
 ELSIF table_value='restaurant_order_events' THEN
  IF operation_value<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport audit retains its actual operation and actor';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported transport effect';END IF;RETURN true;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);order_value text;o restaurant_orders%ROWTYPE;c restaurant_order_changes%ROWTYPE;q restaurant_order_quotes%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;origin _dg_native_order_quote_origins%ROWTYPE;config restaurant_pos_configs%ROWTYPE;hold restaurant_inventory_reservations%ROWTYPE;payload jsonb;expected_quantity bigint;
BEGIN
 IF TG_TABLE_NAME='restaurant_pos_configs' THEN
  SELECT * INTO config FROM restaurant_pos_configs WHERE restaurant_id=j->>'restaurant_id';
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_pos_revisions revision JOIN _dg_native_dining_actions action ON action.id=revision.action_id WHERE revision.restaurant_id=config.restaurant_id AND revision.version=config.version AND revision.provider_id=config.provider_id AND revision.enabled=config.enabled AND revision.scenario=config.scenario AND action.kind='order_config' AND action.resource_id=config.restaurant_id AND action.created_at=config.updated_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS configuration requires its immutable current revision';END IF;RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='restaurant_orders' THEN order_value:=j->>'id';
 ELSIF TG_TABLE_NAME='restaurant_order_changes' THEN order_value:=j->>'order_id';
 ELSE SELECT change.order_id INTO order_value FROM restaurant_order_changes change WHERE change.id=j->>'change_id';END IF;
 SELECT current_order.* INTO o FROM restaurant_orders current_order JOIN _dg_native_order_origins fixed ON fixed.order_id=current_order.id JOIN _dg_native_dining_actions action ON action.id=fixed.action_id JOIN dining_parties party ON party.id=fixed.party_id WHERE current_order.id=order_value AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.party_id=current_order.party_id AND current_order.restaurant_id=party.restaurant_id AND fixed.created_at=current_order.created_at AND action.created_at=fixed.created_at AND action.kind='order_draft' AND action.resource_id=party.id;
 IF o.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order and party require their original scoped creation';END IF;
 IF o.pending_change_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM restaurant_order_changes pending WHERE pending.id=o.pending_change_id AND pending.order_id=o.id AND (pending.status=o.status OR pending.status='unknown' AND o.status='needs_attention' OR o.control_mode='human' AND o.status='needs_attention') AND pending.status IN('draft','awaiting_confirmation','confirmed','queued','submitting','submitted','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pending order state must match its current change';END IF;
 IF TG_TABLE_NAME='restaurant_order_changes' THEN
  SELECT * INTO c FROM restaurant_order_changes WHERE id=j->>'id';
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_change_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=c.id AND fixed.order_id=o.id AND fixed.party_id=o.party_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.created_at=c.created_at AND action.created_at=fixed.created_at AND action.kind='order_draft' AND action.resource_id=o.party_id) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_change_revisions revision WHERE revision.change_id=c.id AND revision.version=c.version AND revision.row_hash=dg_native_office_hash(to_jsonb(c))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Changes retain their origin and exact immutable latest revision';END IF;
  IF c.status IN('awaiting_confirmation','confirmed','queued','submitting','submitted','unknown','accepted','rejected') AND NOT EXISTS(SELECT 1 FROM restaurant_order_quotes quote WHERE quote.id=c.current_quote_id AND quote.change_id=c.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A reviewed change requires its original quote';END IF;
  IF c.status IN('confirmed','queued','submitting','submitted','unknown','accepted','rejected') AND(c.confirmed_at IS NULL OR c.confirmed_actor_id IS NULL OR c.confirmed_quote_id IS DISTINCT FROM c.current_quote_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Confirmed changes retain their actual explicit confirmation';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_quotes' THEN
  SELECT * INTO q FROM restaurant_order_quotes WHERE id=j->>'id';SELECT * INTO origin FROM _dg_native_order_quote_origins WHERE quote_id=q.id;SELECT * INTO c FROM restaurant_order_changes WHERE id=q.change_id;payload:=q.payload::jsonb;
  IF origin.quote_id IS NULL OR origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.payload_hash<>q.hash OR q.hash<>dg_native_office_hash(payload) OR origin.created_at<>q.created_at OR origin.expires_at<>q.expires_at OR payload->>'id'<>q.id OR payload->>'changeId'<>c.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR payload->>'partyId'<>o.party_id OR payload->>'expiresAt'<>q.expires_at OR origin.actor_meta->>'actorId' IS DISTINCT FROM q.actor_id OR origin.actor_meta->>'sessionId' IS DISTINCT FROM q.session_id OR(origin.actor_meta->>'focusVersion')::bigint IS DISTINCT FROM q.focus_version OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=origin.action_id AND action.kind='order_review' AND action.resource_id=o.party_id AND action.created_at=q.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote payload, actor, hash and original deadline require the same review';END IF;
  IF EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=origin.action_id AND action.transaction_id=pg_current_xact_id()::text) AND(q.expires_at<=dg_native_dining_now() OR NOT dg_native_order_source(origin.actor_meta,o.party_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A new quote cannot commit with an expired source';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=j->>'change_id';SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;payload:=d.request_payload::jsonb;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_dispatch_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=d.change_id AND fixed.quote_id=q.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.request_hash=d.request_hash AND action.kind='order_submit' AND action.resource_id=o.party_id AND action.created_at=d.created_at AND fixed.created_at=d.created_at) OR d.request_hash<>dg_native_office_hash(payload) OR d.restaurant_id<>o.restaurant_id OR payload->>'requestId'<>c.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR(d.config_snapshot::jsonb->>'version')::bigint<>d.config_version OR d.config_snapshot::jsonb->>'provider_id'<>d.provider_id OR d.status='queued' AND(c.status<>'queued' OR o.pending_change_id IS DISTINCT FROM c.id) OR d.status='cancelled' AND c.status NOT IN('withdrawn','stale') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch is the original confirmed atomic request and matching state';END IF;
  IF EXISTS(SELECT 1 FROM(SELECT value->>'skuId' sku_id,sum((value->>'quantity')::bigint) quantity FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' GROUP BY value->>'skuId') totals WHERE NOT EXISTS(SELECT 1 FROM restaurant_inventory_reservations reservation JOIN _dg_native_order_reservation_origins fixed ON fixed.reservation_id=reservation.id WHERE reservation.change_id=c.id AND reservation.sku_id=totals.sku_id AND reservation.quantity=totals.quantity AND reservation.status=(CASE WHEN d.status IN('queued','submitting','submitted','unknown') THEN 'reserved' WHEN d.status='accepted' THEN 'committed' ELSE 'released' END))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every submitted add has the exact aggregated atomic reservation';END IF;
 ELSIF TG_TABLE_NAME='restaurant_inventory_reservations' THEN
  SELECT * INTO hold FROM restaurant_inventory_reservations WHERE id=j->>'id';SELECT * INTO c FROM restaurant_order_changes WHERE id=hold.change_id;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;
  SELECT sum((value->>'quantity')::bigint) INTO expected_quantity FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' AND value->>'skuId'=hold.sku_id;
  IF hold.quantity IS DISTINCT FROM expected_quantity OR d.change_id IS NULL OR hold.status IS DISTINCT FROM(CASE WHEN d.status IN('queued','submitting','submitted','unknown') THEN 'reserved' WHEN d.status='accepted' THEN 'committed' ELSE 'released' END) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_reservation_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.reservation_id=hold.id AND fixed.change_id=c.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND action.kind='order_submit' AND action.resource_id=o.party_id AND fixed.created_at=hold.created_at AND action.created_at=hold.created_at) OR(hold.tracked=1) IS DISTINCT FROM(SELECT bool_and((value->>'tracked')::boolean) FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' AND value->>'skuId'=hold.sku_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Inventory holds originate in the same confirmed quote and submit';END IF;
  IF hold.tracked=1 AND(SELECT coalesce(sum(before_quantity-after_quantity),0) FROM restaurant_stock_movements WHERE change_id=c.id AND sku_id=hold.sku_id AND kind IN('reserve','release'))<>(CASE WHEN hold.status IN('reserved','committed') THEN hold.quantity ELSE 0 END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Tracked reservation net movements must equal the retained quantity';END IF;
 END IF;RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_receipt_business(change_value text,event_value text,action_value text,status_value text,receipt jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;q restaurant_order_quotes%ROWTYPE;hold restaurant_inventory_reservations%ROWTYPE;line restaurant_order_lines%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;snapshot jsonb;item jsonb;created text;ticket_value text;current_total bigint;changed boolean:=false;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;snapshot:=q.payload::jsonb;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;
 IF q.id IS NULL OR o.pending_change_id IS DISTINCT FROM c.id OR o.content_version<>(snapshot->>'contentVersion')::bigint OR current_total<>(snapshot->>'oldTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_DATA_INCOMPLETE');END IF;
 IF status_value='accepted' THEN
  FOR hold IN SELECT reservation.* FROM restaurant_inventory_reservations reservation JOIN _dg_native_order_reservation_origins origin ON origin.reservation_id=reservation.id WHERE reservation.change_id=c.id AND reservation.status='reserved' ORDER BY reservation.sku_id FOR UPDATE OF reservation LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_inventory_reservations',hold.id);UPDATE restaurant_inventory_reservations SET status='committed',updated_at=created WHERE id=hold.id;
  END LOOP;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' ORDER BY value->>'lineId' LOOP
   SELECT * INTO line FROM restaurant_order_lines WHERE id=item->>'lineId' AND order_id=o.id FOR UPDATE;SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE line_id=line.id FOR UPDATE;
   IF line.id IS NULL OR ticket.id IS NULL OR ticket.pending_cancel_quantity<(item->>'quantity')::bigint OR line.quantity-line.cancelled_quantity-ticket.started_quantity<(item->>'quantity')::bigint THEN PERFORM dg_native_order_error('KITCHEN_QUANTITY_CHANGED');END IF;
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',line.id);UPDATE restaurant_order_lines SET cancelled_quantity=cancelled_quantity+(item->>'quantity')::bigint WHERE id=line.id;
   PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket.id);UPDATE restaurant_kitchen_tickets SET pending_cancel_quantity=pending_cancel_quantity-(item->>'quantity')::bigint,version=version+1,updated_at=created WHERE id=ticket.id;
  END LOOP;
  -- Return each original tracked SKU once for trusted, accepted reductions.
  FOR item IN SELECT jsonb_build_object('skuId',value->>'skuId','quantity',sum((value->>'quantity')::bigint)) FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' AND(value->>'tracked')::boolean GROUP BY value->>'skuId' ORDER BY value->>'skuId' LOOP
   PERFORM dg_native_order_stock_move(action_value,c.id,item->>'skuId',(item->>'quantity')::bigint,'cancel_return');changed:=true;
  END LOOP;
  IF changed THEN PERFORM dg_native_dining_effect(action_value,'restaurants',o.restaurant_id);UPDATE restaurants SET menu_version=menu_version+1,updated_at=created WHERE id=o.restaurant_id;END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='add' LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',item->>'lineId');INSERT INTO restaurant_order_lines(id,order_id,change_id,item_id,sku_id,item_name,sku_name,unit_price_minor,quantity,preparation_note,dietary_tags,stock_tracked,created_at) VALUES(item->>'lineId',o.id,c.id,item->>'itemId',item->>'skuId',item->>'itemName',item->>'skuName',(item->>'unitPriceMinor')::bigint,(item->>'quantity')::bigint,item->>'preparationNote',(item->'dietaryTags')::text,CASE WHEN(item->>'tracked')::boolean THEN 1 ELSE 0 END,created);
   INSERT INTO _dg_native_order_line_origins VALUES(item->>'lineId',c.id,event_value,q.id,dg_native_office_hash(item),(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
   ticket_value:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket_value);INSERT INTO restaurant_kitchen_tickets(id,restaurant_id,order_id,line_id,table_id,table_name,table_code,accepted_at,updated_at) VALUES(ticket_value,o.restaurant_id,o.id,item->>'lineId',snapshot->>'tableId',snapshot->>'tableName',snapshot->>'tableCode',created,created);INSERT INTO _dg_native_order_kitchen_origins VALUES(ticket_value,item->>'lineId',event_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
  END LOOP;
  SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;IF current_total<>(snapshot->>'newTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_AMOUNT_INVALID');END IF;
 ELSE PERFORM dg_native_order_inventory(action_value,c.id,q.id,false);END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_quotes',q.id);UPDATE restaurant_order_quotes SET status=status_value WHERE id=q.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=status_value,version=version+1,updated_at=created WHERE id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status=status_value,last_sequence=(receipt->>'sequence')::bigint,remote_request_id=receipt->>'remoteRequestId',remote_order_id=receipt->>'remoteOrderId',lease_token=NULL,lease_until=NULL,query_requested=0,error_code=CASE WHEN status_value='rejected' THEN 'POS_REJECTED' END,error_message=CASE WHEN status_value='rejected' THEN '模拟后厨明确拒绝本次变更，预占已释放。' END,version=version+1,updated_at=created WHERE change_id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET pending_change_id=NULL,content_version=content_version+CASE WHEN status_value='accepted' THEN 1 ELSE 0 END,remote_order_id=CASE WHEN status_value='accepted' THEN receipt->>'remoteOrderId' ELSE remote_order_id END,status=dg_native_order_status(o.id),attention_reason=CASE WHEN control_mode='human' THEN attention_reason END,version=version+1,updated_at=created WHERE id=o.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_pos_callbacks',event_value);UPDATE restaurant_pos_callbacks SET applied=1 WHERE event_id=event_value;PERFORM dg_native_order_event(action_value,o.id,c.id,'order_receipt',CASE WHEN status_value='accepted' THEN '模拟后厨已确认，价格快照和制作项目已持久保存，尚未结算。' ELSE '模拟后厨明确拒绝此次变更，原已接单内容保留。' END);
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_withdraw_internal(change_value text,action_value text,expired_value boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;created text;quote_value text;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value FOR UPDATE;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id FOR UPDATE;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 IF o.pending_change_id IS DISTINCT FROM c.id AND NOT(c.status='rejected' AND o.pending_change_id IS NULL) THEN PERFORM dg_native_order_error('ORDER_CHANGE_PENDING');END IF;
 IF c.status NOT IN('draft','awaiting_confirmation','confirmed','queued','rejected','stale') THEN PERFORM dg_native_order_error('ORDER_RESULT_PENDING');END IF;
 IF c.status='queued' THEN
  IF d.status<>'queued' OR d.attempts<>0 THEN PERFORM dg_native_order_error('ORDER_RESULT_PENDING');END IF;
  PERFORM dg_native_order_inventory(action_value,c.id,c.confirmed_quote_id,false);PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status='cancelled',version=version+1,error_code=CASE WHEN expired_value THEN 'ORDER_SOURCE_EXPIRED' END,error_message=CASE WHEN expired_value THEN '未发送请求的原期限或来源已失效，预占已释放。' END,updated_at=created WHERE change_id=c.id;
 END IF;
 FOR quote_value IN SELECT id FROM restaurant_order_quotes WHERE change_id=c.id AND status='current' LOOP PERFORM dg_native_dining_effect(action_value,'restaurant_order_quotes',quote_value);UPDATE restaurant_order_quotes SET status=CASE WHEN expired_value AND expires_at<=dg_native_dining_now() THEN 'expired' ELSE 'withdrawn' END WHERE id=quote_value;END LOOP;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=CASE WHEN expired_value THEN 'stale' ELSE 'withdrawn' END,version=version+1,updated_at=created WHERE id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET pending_change_id=NULL,status=CASE WHEN NOT EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id AND quantity>cancelled_quantity) THEN 'cancelled' ELSE dg_native_order_status(o.id) END,version=version+1,updated_at=created WHERE id=o.id;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE o restaurant_orders%ROWTYPE;p dining_parties%ROWTYPE;c restaurant_order_changes%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;line restaurant_order_lines%ROWTYPE;t restaurant_kitchen_tickets%ROWTYPE;sku restaurant_menu_skus%ROWTYPE;item restaurant_menu_items%ROWTYPE;draft_line jsonb;previews jsonb;quote jsonb;lines jsonb:='[]';changes jsonb:='[]';events jsonb;reason text;accepted_total bigint:=0;pending_total bigint;active bigint;state_value text;
BEGIN
 SELECT current_order.* INTO o FROM restaurant_orders current_order JOIN _dg_native_order_origins origin ON origin.order_id=current_order.id WHERE current_order.id=target AND current_order.restaurant_id=meta->>'restaurantId' AND current_order.party_id=meta->>'partyId';IF o.id IS NULL THEN PERFORM dg_native_order_error('NOT_FOUND');END IF;SELECT * INTO p FROM dining_parties WHERE id=o.party_id;
 FOR line IN SELECT * FROM restaurant_order_lines WHERE order_id=o.id ORDER BY created_at,id LOOP
  SELECT * INTO t FROM restaurant_kitchen_tickets WHERE line_id=line.id;IF t.id IS NULL THEN PERFORM dg_native_order_error('ORDER_DATA_INCOMPLETE');END IF;active:=line.quantity-line.cancelled_quantity;accepted_total:=accepted_total+active*line.unit_price_minor;
  state_value:=CASE WHEN active=0 THEN 'cancelled' WHEN t.served_quantity>=active THEN 'served' WHEN t.ready_quantity>=active THEN 'ready' WHEN t.started_quantity>0 THEN 'preparing' ELSE 'accepted' END;
  lines:=lines||jsonb_build_array(jsonb_build_object('id',line.id,'skuId',line.sku_id,'itemId',line.item_id,'itemName',line.item_name,'skuName',line.sku_name,'unitPriceMinor',line.unit_price_minor,'currency','CNY','quantity',line.quantity,'cancelledQuantity',line.cancelled_quantity,'activeQuantity',active,'preparationNote',line.preparation_note,'dietaryTags',line.dietary_tags::jsonb,'subtotalMinor',active*line.unit_price_minor,'kitchen',jsonb_build_object('ticketId',t.id,'version',t.version,'startedQuantity',t.started_quantity,'readyQuantity',t.ready_quantity,'servedQuantity',t.served_quantity,'pendingCancelQuantity',t.pending_cancel_quantity,'state',state_value)));
 END LOOP;
 FOR c IN SELECT * FROM restaurant_order_changes WHERE order_id=o.id ORDER BY sequence LOOP
  previews:='[]';FOR draft_line IN SELECT * FROM jsonb_array_elements(c.input::jsonb->'newLines') LOOP
   SELECT * INTO sku FROM restaurant_menu_skus WHERE id=draft_line->>'skuId';SELECT * INTO item FROM restaurant_menu_items WHERE id=sku.item_id;
   previews:=previews||jsonb_build_array(jsonb_build_object('skuId',draft_line->>'skuId','itemName',coalesce(item.name,'当前菜品不可用'),'skuName',coalesce(sku.name,'规格不可用'),'quantity',(draft_line->>'quantity')::bigint,'preparationNote',draft_line->>'preparationNote','currentPriceMinor',sku.price_minor,'available',coalesce(sku.archived=0 AND sku.on_sale=1 AND item.listed=1 AND(sku.stock_tracked=0 OR sku.stock_remaining>0),false),'reason',CASE WHEN sku.id IS NULL OR sku.archived<>0 OR sku.on_sale<>1 OR item.listed<>1 OR sku.stock_tracked=1 AND sku.stock_remaining=0 THEN '当前规格已停售、下架或无可售数量。' END));
  END LOOP;
  quote:=dg_native_order_quote_project(c.current_quote_id,meta);SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;
  changes:=changes||jsonb_build_array(jsonb_build_object('id',c.id,'orderId',o.id,'sequence',c.sequence,'kind',c.kind,'version',c.version,'status',c.status,'source',c.source,'input',c.input::jsonb,'newLinePreviews',previews,'currentQuote',quote,'dispatch',CASE WHEN d.change_id IS NOT NULL THEN jsonb_build_object('id',d.change_id,'version',d.version,'status',d.status,'simulated',d.simulated=1,'attempts',d.attempts,'queryRequested',d.query_requested=1,'lookups',d.lookups,'remoteRequestId',d.remote_request_id,'remoteOrderId',d.remote_order_id,'errorCode',d.error_code,'errorMessage',d.error_message,'createdAt',d.created_at,'updatedAt',d.updated_at) END,'confirmedAt',c.confirmed_at,'createdAt',c.created_at,'updatedAt',c.updated_at));
  IF o.pending_change_id=c.id AND quote IS NOT NULL THEN pending_total:=(quote->>'newTotalMinor')::bigint;END IF;
 END LOOP;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'kind',e.kind,'message',e.info::jsonb->>'message','createdAt',e.created_at) ORDER BY e.created_at,e.id),'[]') INTO events FROM(SELECT * FROM restaurant_order_events WHERE order_id=o.id ORDER BY created_at DESC,id DESC LIMIT 100) e;
 reason:=CASE WHEN p.status NOT IN('waiting','reserved','held','seated') THEN '本次就餐已结束，请联系店员处理历史记录。' WHEN o.status IN('cancelled','closed') OR o.settlement_status='settled' THEN '本订单已结束，后续点单需建立新订单。' WHEN o.control_mode='human' THEN '本单正在人工核对。' WHEN o.pending_change_id IS NOT NULL THEN '请先处理当前未完成变更。' WHEN meta->>'actorType'='guest' AND(SELECT status FROM reception_sessions WHERE id=meta->>'sessionId')<>'active' THEN '当前会话已暂停自动处理。' END;
 RETURN jsonb_build_object('id',o.id,'restaurantId',o.restaurant_id,'partyId',o.party_id,'number',o.number,'version',o.version,'contentVersion',o.content_version,'status',o.status,'controlMode',o.control_mode,'attentionReason',o.attention_reason,'settlementStatus',o.settlement_status,'acceptedTotalMinor',accepted_total,'pendingTotalMinor',pending_total,'currency','CNY','pendingChangeId',o.pending_change_id,'lines',lines,'changes',changes,'events',events,'canChange',reason IS NULL,'changeReason',reason,'createdAt',o.created_at,'updatedAt',o.updated_at);
END;$dg$;


DO $kitchen_acl$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema() AND(p.proname LIKE 'dg_native_order_kitchen_%' OR p.proname IN('dg_native_order_status','dg_native_order_control')) LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC';END LOOP;END;$kitchen_acl$;
